#!/usr/bin/env python3
"""v15.13: supplied independent events; execution schedules are not clocks.

The two local chains, their carrier, generators, retained algebras and outcomes
are illustrative inputs. This tests confluence, not a physical collapse law.
"""
from __future__ import annotations
import argparse
from dataclasses import dataclass
from functools import lru_cache
import itertools
import json
import math
from pathlib import Path
import numpy as np

EVENTS = ('A1','A2','B1','B2')
PAULIS = {'I':np.eye(2,dtype=complex), 'X':np.array([[0,1],[1,0]],complex),
          'Y':np.array([[0,-1j],[1j,0]],complex), 'Z':np.diag([1.,-1.]).astype(complex)}
TOL = 1e-11
BASE_COMMIT = 'c1b0582d15e0720e3e01989f7aa195ed89e6a62a'


def tensor_word(word: str) -> np.ndarray:
    out=np.ones((1,1),complex)
    for c in word: out=np.kron(out,PAULIS[c])
    return out


def unitary(generator: np.ndarray, extent: float) -> np.ndarray:
    h=np.asarray(generator,complex)
    if h.ndim!=2 or h.shape[0]!=h.shape[1] or not np.all(np.isfinite(h)) or not math.isfinite(extent):
        raise ValueError('finite square generator and extent required')
    if np.linalg.norm(h-h.conj().T)>TOL: raise ValueError('Hermitian generator required')
    vals,vecs=np.linalg.eigh(h)
    return (vecs*np.exp(-1j*extent*vals))@vecs.conj().T


def _seed() -> np.ndarray:
    v=np.ones(16,complex)/4
    return .9*np.outer(v,v.conj())+.1*np.eye(16)/16


def _pretime_unitary() -> np.ndarray:
    g=.39*tensor_word('ZIZI')+.27*tensor_word('IZIZ')+.17*tensor_word('YIII')
    return unitary(g,.9)


def initial_state() -> np.ndarray:
    u=_pretime_unitary()
    return u@_seed()@u.conj().T


def pretime_control() -> dict:
    u=_pretime_unitary(); rho=initial_state()
    shaped=rho.reshape(4,4,4,4)
    a=np.trace(shaped,axis1=1,axis2=3); b=np.trace(shaped,axis1=0,axis2=2)
    pt=shaped.transpose(0,3,2,1).reshape(16,16)
    return {'state_change':distance(rho,_seed()),
            'inverse_error':float(np.linalg.norm(u.conj().T@rho@u-_seed())),
            'product_state_residual':float(np.linalg.norm(rho-np.kron(a,b))),
            'partial_transpose_min_eigenvalue':float(np.linalg.eigvalsh(pt).min()),
            'extent_semantics':'FINITE_TRANSFORMATION_COORDINATE_NOT_TIME'}


def distance(a: np.ndarray,b: np.ndarray) -> float:
    d=a-b
    return float(np.abs(np.linalg.eigvalsh((d+d.conj().T)/2)).sum()/2)


@lru_cache(None)
def projector(qubit: int,bit: int) -> np.ndarray:
    if type(qubit) is not int or not 0<=qubit<4 or type(bit) is not int or bit not in (0,1):
        raise ValueError('qubit 0..3 and binary integer outcome required')
    word='I'*qubit+'Z'+'I'*(3-qubit)
    p=(np.eye(16)+(1 if bit==0 else -1)*tensor_word(word))/2
    p.setflags(write=False)
    return p


@lru_cache(None)
def event_unitary(event: str) -> np.ndarray:
    if event not in EVENTS: raise ValueError('undeclared event')
    g,extent={
      'A1':(.47*tensor_word('YIII')+.19*tensor_word('ZXII'),.65),
      'A2':(.41*tensor_word('IYII')+.17*tensor_word('ZXII'),.55),
      'B1':(.37*tensor_word('IIYI')+.23*tensor_word('IIZX'),-.45),
      'B2':(.43*tensor_word('IIIY')+.13*tensor_word('IIZX'),.70)}[event]
    u=unitary(g,extent); u.setflags(write=False)
    return u


def kraus(event: str,bit: int,*,coupled_control: bool=False) -> np.ndarray:
    if event not in EVENTS: raise ValueError('undeclared event')
    u=event_unitary(event)
    if coupled_control and event=='B1':
        # Deliberately violates independent support. NEVER a physical addition.
        u=unitary(tensor_word('XIXI'),.47)@u
    return projector(EVENTS.index(event),bit)@u


def validate_records(records: str) -> None:
    if not isinstance(records,str) or len(records)!=4 or any(c not in '01' for c in records):
        raise ValueError('supply four binary outcomes in A1,A2,B1,B2 order; none are chosen automatically')


def schedules() -> tuple[tuple[str,...],...]:
    return tuple(s for s in itertools.permutations(EVENTS)
                 if s.index('A1')<s.index('A2') and s.index('B1')<s.index('B2'))


def record_projector(done: tuple[str,...],records: str) -> np.ndarray:
    validate_records(records)
    p=np.eye(16,dtype=complex)
    for e in done:
        q=EVENTS.index(e); p=p@projector(q,int(records[q]))
    return p


def apply_selected(rho: np.ndarray,k: np.ndarray) -> tuple[np.ndarray,float]:
    rho=np.asarray(rho,complex); k=np.asarray(k,complex)
    if rho.shape!=(16,16) or k.shape!=(16,16) or not np.all(np.isfinite(rho)) or not np.all(np.isfinite(k)):
        raise ValueError('finite 16x16 matrices required')
    if np.linalg.norm(rho-rho.conj().T)>TOL or abs(np.trace(rho)-1)>TOL or np.linalg.eigvalsh(rho).min() < -TOL:
        raise ValueError('normalized positive state required')
    out=k@rho@k.conj().T; weight=float(np.trace(out).real)
    if not weight>0: raise ValueError('supplied outcome has zero probability')
    if weight>1+TOL: raise ValueError('selected map is not trace-nonincreasing on this state')
    return out/weight,weight


@dataclass
class Snapshot:
    done: tuple[str,...]
    rho: np.ndarray
    tau: np.ndarray
    mass: float
    conditional_weight: float
    record_rank: int
    event: str | None=None
    moved: np.ndarray | None=None
    coarse: np.ndarray | None=None
    witness_before: float=0.
    witness_after: float=0.


def run(schedule: tuple[str,...],records: str,*,coupled_control: bool=False) -> list[Snapshot]:
    validate_records(records)
    if not isinstance(schedule,(list,tuple)) or tuple(schedule) not in schedules():
        raise ValueError('execution order must respect supplied A1<A2 and B1<B2 dependencies')
    rho=initial_state(); tau=rho.copy(); done=[]
    frames=[Snapshot((),rho,tau,1.,1.,16)]
    for e in schedule:
        q=EVENTS.index(e); bit=int(records[q]); u=event_unitary(e)
        if coupled_control and e=='B1': u=unitary(tensor_word('XIXI'),.47)@u
        moved=u@rho@u.conj().T
        p0,p1=projector(q,0),projector(q,1)
        coarse=p0@moved@p0+p1@moved@p1
        phase=p0-p1; witness=phase@moved@phase
        reduced_witness=p0@witness@p0+p1@witness@p1
        k=projector(q,bit)@u
        rho,conditional=apply_selected(rho,k)
        tau=k@tau@k.conj().T; mass=float(np.trace(tau).real)
        done.append(e); ideal=tuple(sorted(done))
        frames.append(Snapshot(ideal,rho,tau,mass,conditional,16//(2**len(done)),e,moved,coarse,
                               distance(moved,witness),distance(coarse,reduced_witness)))
    return frames


def commutator_residual(*,coupled_control: bool=False) -> float:
    return max(float(np.linalg.norm(ka@kb-kb@ka))
               for a in ('A1','A2') for b in ('B1','B2') for x in (0,1) for y in (0,1)
               for ka,kb in [(kraus(a,x,coupled_control=coupled_control),kraus(b,y,coupled_control=coupled_control))])


def compare_schedules(records: str,*,coupled_control: bool=False) -> dict:
    seen={}; errors=[]; weights=[]; raw=[]; context={e:[] for e in EVENTS}
    trajectories=[run(s,records,coupled_control=coupled_control) for s in schedules()]
    for frames in trajectories:
        for f in frames:
            if f.event: context[f.event].append(f.conditional_weight)
            if f.done in seen:
                other=seen[f.done]
                errors.append(distance(f.rho,other.rho)); weights.append(abs(f.mass-other.mass))
                raw.append(float(np.linalg.norm(f.tau-other.tau)))
            else: seen[f.done]=f
    return {'ideal_count':len(seen),'max_shared_ideal_state_error':max(errors,default=0.),
            'max_shared_ideal_mass_error':max(weights,default=0.),
            'max_shared_ideal_subnormalized_error':max(raw,default=0.),
            'max_contextual_weight_change':max(max(v)-min(v) for v in context.values()),
            'final_mass_range':max(fs[-1].mass for fs in trajectories)-min(fs[-1].mass for fs in trajectories),
            'final_state_error':max(distance(fs[-1].rho,trajectories[0][-1].rho) for fs in trajectories),
            'contextual_weights':context}


def negative_control() -> dict:
    c=compare_schedules('1001',coupled_control=True)
    return {'classification':'DELIBERATELY_COUPLED_CONTROL_NOT_A_PHYSICAL_ADDITION',
            'cross_commutator':commutator_residual(coupled_control=True),
            'shared_ideal_state_error':c['max_shared_ideal_state_error'],
            'joint_mass_difference':c['final_mass_range'],
            'final_normalized_state_error':c['final_state_error']}


def audit() -> dict:
    rows=[compare_schedules(f'{k:04b}') for k in range(16)]
    norm_error=max(abs(sum(run(s,f'{k:04b}')[-1].mass for k in range(16))-1) for s in schedules())
    return {'version':'v15.13','status':'EXECUTED_CONDITIONAL_PARTIAL_ORDER_DEMONSTRATOR',
            'record_assignments':16,'schedules_per_assignment':6,'runs_checked':96,'ideals_per_assignment':9,
            'max_state_error':max(c['max_shared_ideal_state_error'] for c in rows),
            'max_mass_error':max(c['max_shared_ideal_mass_error'] for c in rows),
            'max_subnormalized_error':max(c['max_shared_ideal_subnormalized_error'] for c in rows),
            'max_contextual_weight_change':max(c['max_contextual_weight_change'] for c in rows),
            'joint_distribution_normalization_error':float(norm_error),
            'cross_stream_kraus_commutator':commutator_residual(),
            'pretime':pretime_control(),'negative_control':negative_control(),
            'physical_duration':None,'new_physical_axioms':[],'source_law_derived':False,
            'entropy_production_derived':False,'Pillar_3':'OPEN','scientific_breakthrough':False,
            'scope':'Carrier, instruments, local dependencies, and actual records supplied; only their computational interleaving is varied.'}


def _snapshot_json(f: Snapshot,records: str) -> dict:
    a=''.join(records[EVENTS.index(e)] for e in ('A1','A2') if e in f.done)
    b=''.join(records[EVENTS.index(e)] for e in ('B1','B2') if e in f.done)
    return {'done':list(f.done),'coordinates':[len(a),len(b)],'records':[a,b],
            'mass':f.mass,'conditional_weight':f.conditional_weight,'record_rank':f.record_rank,
            'event':f.event,'witness_before':f.witness_before,'witness_after':f.witness_after,
            'probabilities':np.diag(f.rho).real.tolist(),
            'rho_real':f.rho.real.tolist(),'rho_imag':f.rho.imag.tolist()}


def build_payload() -> dict:
    branches={}
    for k in range(16):
        r=f'{k:04b}'
        branches[r]=[{'schedule':list(s),'snapshots':[_snapshot_json(f,r) for f in run(s,r)]} for s in schedules()]
    return {'version':'v15.13','default_records':'1001','branches':branches,'audit':audit(),
            'notice':'Playback steps and lattice coordinates are display conventions, not duration, simultaneity or space.'}


def main() -> None:
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--out',type=Path,default=Path('outputs'))
    args=parser.parse_args(); args.out.mkdir(parents=True,exist_ok=True)
    payload=build_payload(); result=payload['audit']
    if max(result['max_state_error'],result['max_mass_error'],result['cross_stream_kraus_commutator'])>TOL:
        raise SystemExit('confluence verification failed; no positive adjudication')
    (args.out/'replay_data.json').write_text(json.dumps(payload,separators=(',',':'),allow_nan=False)+'\n')
    (args.out/'verification.json').write_text(json.dumps(result,indent=2,allow_nan=False)+'\n')
    print(json.dumps(result,indent=2,allow_nan=False))

if __name__=='__main__': main()

#!/usr/bin/env python3
"""v15.14: supplied record-read dependency, not a physical clock/collapse law."""
from __future__ import annotations
import argparse
from dataclasses import dataclass
from functools import lru_cache
import hashlib
import itertools
import json
from pathlib import Path
from types import MappingProxyType
from typing import Mapping
import numpy as np
from vendor import v1513 as base

ROOT=Path(__file__).resolve().parent
EVENTS=base.EVENTS
READS=MappingProxyType({'A1':(), 'A2':('A1',), 'B1':(), 'B2':('A1','B1')})
VENDOR_BLOB='95d0303d617422d74e61ae017f0354233ec9454b'
TOL=1e-11

class MissingRecord(ValueError):
    """The instrument is unavailable on this realized record prefix."""


def verify_vendor() -> str:
    data=(ROOT/'vendor/v1513.py').read_bytes()
    sha=hashlib.sha1(f'blob {len(data)}\0'.encode()+data).hexdigest()
    if sha!=VENDOR_BLOB: raise ValueError('v15.13 source hash mismatch')
    return sha


def edges() -> tuple[tuple[str,str],...]:
    return tuple((r,e) for e in EVENTS for r in READS[e])


def schedules() -> tuple[tuple[str,...],...]:
    return tuple(s for s in itertools.permutations(EVENTS)
                 if all(s.index(a)<s.index(b) for a,b in edges()))


def _frozen(a: np.ndarray) -> np.ndarray:
    # bytes-backed arrays prevent callers from re-enabling WRITEABLE.
    out=np.frombuffer(np.asarray(a,dtype=complex).tobytes(),dtype=complex).reshape(16,16)
    return out


@dataclass(frozen=True)
class Snapshot:
    records: tuple[tuple[str,int],...]
    rho: np.ndarray
    tau: np.ndarray
    mass: float
    conditional_weight: float
    event: str | None=None
    control_bit: int | None=None

    @property
    def done(self) -> tuple[str,...]:
        return tuple(e for e,_ in self.records)


def start() -> Snapshot:
    verify_vendor(); r=base.initial_state()
    return Snapshot((),_frozen(r),_frozen(r),1.,1.)


def missing(frame: Snapshot,event: str) -> tuple[str,...]:
    if event not in EVENTS: raise ValueError('undeclared event')
    return tuple(e for e in READS[event] if e not in frame.done)


def enabled(frame: Snapshot) -> tuple[str,...]:
    return tuple(e for e in EVENTS if e not in frame.done and not missing(frame,e))


def instrument(event: str, realized_reads: Mapping[str,int]) -> np.ndarray:
    """Only declared ALREADY REALIZED record values enter this resolver.

    B2's extra rotation is a supplied finite operation on the second B qubit:
    exp(-i s(a) Y_B2), s(0)=+0.6, s(1)=-0.6. It is not a fitted dynamics law.
    The actual B2 outcome is not an argument to the instrument resolver.
    """
    if event not in EVENTS: raise ValueError('undeclared event')
    if not isinstance(realized_reads,Mapping): raise ValueError('realized read mapping required')
    absent=set(READS[event])-set(realized_reads)
    if absent: raise MissingRecord(f'{event} requires realized records: {", ".join(sorted(absent))}')
    if set(realized_reads)!=set(READS[event]):
        raise ValueError('only declared realized read keys may be supplied')
    if any(type(v) is not int or v not in (0,1) for v in realized_reads.values()):
        raise ValueError('binary integer record values required')
    u=base.event_unitary(event)
    if event=='B2':
        extent=.6 if realized_reads['A1']==0 else -.6
        u=base.unitary(base.tensor_word('IIIY'),extent)@u
    return u


def advance(frame: Snapshot,event: str,outcome: int) -> Snapshot:
    if type(outcome) is not int or outcome not in (0,1): raise ValueError('supply the actual binary record')
    if event not in EVENTS: raise ValueError('undeclared event')
    if event in frame.done: raise ValueError('an actual record cannot be overwritten or repeated')
    if missing(frame,event):
        raise MissingRecord(f'{event} blocked: missing {", ".join(missing(frame,event))}')
    record=dict(frame.records)
    reads={e:record[e] for e in READS[event]}
    u=instrument(event,reads)
    k=base.projector(EVENTS.index(event),outcome)@u
    rho,conditional=base.apply_selected(frame.rho,k)
    tau=k@frame.tau@k.conj().T; mass=float(np.trace(tau).real)
    record[event]=outcome
    pairs=tuple((e,record[e]) for e in EVENTS if e in record)
    p=np.eye(16,dtype=complex)
    for e,b in pairs: p=p@base.projector(EVENTS.index(e),b)
    if np.linalg.norm(p@rho@p-rho)>TOL or abs(np.trace(rho)-1)>TOL or np.linalg.eigvalsh(rho).min() < -TOL:
        raise ArithmeticError('state or retained-record invariant failed')
    return Snapshot(pairs,_frozen(rho),_frozen(tau),mass,conditional,event,reads.get('A1') if event=='B2' else None)


def run(schedule: tuple[str,...],actual_records: str) -> tuple[Snapshot,...]:
    base.validate_records(actual_records)
    if not isinstance(schedule,(list,tuple)) or len(schedule)!=4 or set(schedule)!=set(EVENTS):
        raise ValueError('each of the four declared events must appear exactly once')
    f=start(); frames=[f]
    for event in schedule:
        # advance first tests realized availability; the complete script never
        # reaches the instrument resolver or readiness functions.
        f=advance(f,event,int(actual_records[EVENTS.index(event)])); frames.append(f)
    return tuple(frames)


def control_channel_distance() -> float:
    # Distinguish full labeled instrument channels, not merely Kraus phases.
    choi=[]
    for a in (0,1):
        u=instrument('B2',{'A1':a,'B1':0})
        blocks=[]
        for b in (0,1):
            k=base.projector(3,b)@u; v=k.reshape(-1,order='F')
            blocks.append(np.outer(v,v.conj()))
        choi.append(blocks)
    return float(np.sqrt(sum(np.linalg.norm(x-y)**2 for x,y in zip(*choi))))


def _unsafe_guess_run(records: str,guess: int) -> tuple[np.ndarray,float]:
    """Explicitly rejected bypass: use guessed A1 before A1 is realized."""
    rho=base.initial_state(); tau=rho.copy()
    for event in ('B1','B2','A1','A2'):
        # This deliberately violates the record-availability interface.
        u=instrument('B2',{'A1':guess,'B1':int(records[2])}) if event=='B2' else base.event_unitary(event)
        k=base.projector(EVENTS.index(event),int(records[EVENTS.index(event)]))@u
        rho,_=base.apply_selected(rho,k); tau=k@tau@k.conj().T
    return rho,float(np.trace(tau).real)


def guess_controls() -> list[dict]:
    rows=[]
    for guess in (0,1):
        errors=[]; distances=[]; guessed_mass=[]
        for k in range(16):
            records=f'{k:04b}'; correct=run(schedules()[0],records)[-1]
            wrong,weight=_unsafe_guess_run(records,guess)
            errors.append(abs(weight-correct.mass)); distances.append(base.distance(wrong,correct.rho)); guessed_mass.append(weight)
        rows.append({'status':'REJECTED_RECORD_GUESS_CONTROL','guessed_A1':guess,
                     'max_joint_mass_error':max(errors),'total_variation':float(sum(errors)/2),
                     'max_final_state_distance':max(distances),
                     'guessed_distribution_normalization_error':abs(sum(guessed_mass)-1)})
    return rows


def collect() -> dict[str,list[tuple[Snapshot,...]]]:
    return {f'{k:04b}':[run(s,f'{k:04b}') for s in schedules()] for k in range(16)}


def audit() -> dict:
    data=collect(); state=mass=raw=persist=traceerr=0.; mineig=1.; ideals=set()
    for runs in data.values():
        seen={}
        for frames in runs:
            for f in frames:
                ideals.add(f.done)
                traceerr=max(traceerr,float(abs(np.trace(f.rho)-1)))
                mineig=min(mineig,float(np.linalg.eigvalsh(f.rho).min()))
                if f.done in seen:
                    g=seen[f.done]
                    state=max(state,base.distance(f.rho,g.rho)); mass=max(mass,abs(f.mass-g.mass))
                    raw=max(raw,float(np.linalg.norm(f.tau-g.tau)))
                else: seen[f.done]=f
    norm=max(abs(sum(runs[i][-1].mass for runs in data.values())-1) for i in range(len(schedules())))
    # Permissible incomparable pairs must commute at each shared controller value.
    comm=0.
    incomparable=[('A1','B1'),('A2','B1'),('A2','B2')]
    for controller in (0,1):
        for a,b in incomparable:
            ua=instrument(a,{e:controller for e in READS[a]}); ub=instrument(b,{e:controller for e in READS[b]})
            for x,y in itertools.product((0,1),repeat=2):
                ka=base.projector(EVENTS.index(a),x)@ua; kb=base.projector(EVENTS.index(b),y)@ub
                comm=max(comm,float(np.linalg.norm(ka@kb-kb@ka)))
    rejected=0
    for s in itertools.permutations(EVENTS):
        try: run(s,'1001')
        except MissingRecord: rejected+=1
    result={'version':'v15.14','status':'EXECUTED_CONDITIONAL_RECORD_DEPENDENT_DEMONSTRATOR',
            'record_rule_status':'SUPPLIED_ILLUSTRATIVE_FEED_FORWARD','extra_record_read':['A1','B2'],
            'local_schedules_before_read':6,'valid_schedules_after_read':len(schedules()),
            'record_assignments':16,'runs_checked':sum(len(r) for r in data.values()),'ideals_per_assignment':len(ideals),
            'premature_permutations_rejected':rejected,'max_state_distance':state,'max_mass_error':mass,
            'max_subnormalized_error':raw,'max_trace_error':traceerr,'min_state_eigenvalue':mineig,
            'joint_distribution_normalization_error':float(norm),'max_incomparable_commutator':comm,
            'control_channel_choi_distance':control_channel_distance(),'guessed_record_controls':guess_controls(),
            'pretime_control':base.pretime_control(),'physical_duration':None,
            'physical_causality_derived':False,'physical_entropy_law_derived':False,'collapse_outcome_derived':False,
            'new_physical_axioms':[],'Pillar_3':'OPEN','scientific_breakthrough':False,
            'vendor_git_blob':verify_vendor(),
            'scope':'The record wire, finite controller values, carrier, RAS and RCR remain supplied. Readiness follows that declaration, not an externally imposed clock.'}
    if max(state,mass,raw,traceerr,norm,comm)>TOL or mineig < -TOL or rejected!=19:
        raise ArithmeticError('verification failed; no positive adjudication')
    return result


def snapshot_json(f: Snapshot) -> dict:
    return {'done':list(f.done),'records':dict(f.records),'enabled':list(enabled(f)),
            'blocked':{e:list(missing(f,e)) for e in EVENTS if e not in f.done and missing(f,e)},
            'mass':f.mass,'conditional_weight':f.conditional_weight,'event':f.event,'control_bit':f.control_bit,
            'record_rank':16//2**len(f.done),'probabilities':np.diag(f.rho).real.tolist(),
            'rho_real':f.rho.real.tolist(),'rho_imag':f.rho.imag.tolist()}


def payload() -> dict:
    return {'version':'v15.14','default_records':'1001','edges':[list(e) for e in edges()],
            'schedules':[list(s) for s in schedules()],
            'branches':{r:[{'snapshots':[snapshot_json(f) for f in fs]} for fs in runs] for r,runs in collect().items()},
            'audit':audit(),'display_warning':'Playback is not physical time. Dependencies and actual outcomes are supplied inputs.'}


def main() -> None:
    p=argparse.ArgumentParser(description=__doc__); p.add_argument('--out',type=Path,default=ROOT/'outputs')
